CREATE TABLE IF NOT EXISTS eco_config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO eco_config VALUES('gold_starts_at',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO eco_config VALUES('public_enabled','1');
INSERT OR IGNORE INTO eco_config VALUES('pix_enabled','0');
INSERT OR IGNORE INTO eco_config VALUES('pix_url','https://nubank.com.br/cobrar/3uagb/6ad25990-2ac2-45cf-9cbb-94a5f6fdbce7');
INSERT OR IGNORE INTO eco_config VALUES('supplier_json','{}');
CREATE TABLE IF NOT EXISTS eco_wallets(user TEXT PRIMARY KEY REFERENCES accounts(user),gold_units INTEGER NOT NULL DEFAULT 0 CHECK(gold_units>=0),bcoin_units INTEGER NOT NULL DEFAULT 0 CHECK(bcoin_units>=0),updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_ledger(id TEXT PRIMARY KEY,user TEXT NOT NULL REFERENCES accounts(user),kind TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('gold','bcoin')),delta_units INTEGER NOT NULL,balance_after INTEGER NOT NULL CHECK(balance_after>=0),reference TEXT NOT NULL,created_at TEXT NOT NULL,details_json TEXT NOT NULL,UNIQUE(user,kind,reference));
CREATE INDEX IF NOT EXISTS eco_ledger_user_at ON eco_ledger(user,created_at DESC);
CREATE TABLE IF NOT EXISTS eco_ops(user TEXT NOT NULL,op_id TEXT NOT NULL,request_hash TEXT NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(user,op_id));
CREATE TABLE IF NOT EXISTS eco_brands(user TEXT NOT NULL REFERENCES accounts(user),brand_key TEXT NOT NULL,acquired_at TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(user,brand_key));
CREATE TABLE IF NOT EXISTS eco_selected(user TEXT PRIMARY KEY,brand_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_orders(id TEXT PRIMARY KEY,user TEXT NOT NULL REFERENCES accounts(user),product_id TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,amount_centavos INTEGER NOT NULL,currency TEXT NOT NULL,price_units INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,payment_claim_json TEXT,payment_id TEXT UNIQUE,confirmed_by TEXT,fulfilled_at TEXT);
CREATE INDEX IF NOT EXISTS eco_orders_user ON eco_orders(user,created_at DESC);
CREATE TABLE IF NOT EXISTS eco_pix_receipts(payment_id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE,amount_centavos INTEGER NOT NULL,actor TEXT NOT NULL,confirmed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_products(id TEXT PRIMARY KEY,kind TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,gold_units INTEGER NOT NULL DEFAULT 0,bcoin_units INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS eco_entitlements(user TEXT NOT NULL,product_id TEXT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,acquired_at TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(user,product_id));
CREATE TABLE IF NOT EXISTS eco_journeys(user TEXT NOT NULL,mission_id TEXT NOT NULL,evidence_json TEXT NOT NULL,PRIMARY KEY(user,mission_id));
CREATE TABLE IF NOT EXISTS eco_rewards(user TEXT NOT NULL,delivery_id INTEGER NOT NULL,mission_id TEXT NOT NULL,gat_points INTEGER NOT NULL,gold_units INTEGER NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(user,delivery_id),UNIQUE(user,mission_id));
CREATE TABLE IF NOT EXISTS eco_companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,tag TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',owner_user TEXT NOT NULL REFERENCES accounts(user),capacity INTEGER NOT NULL CHECK(capacity>=1),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_company_members(user TEXT PRIMARY KEY REFERENCES accounts(user),company_id TEXT NOT NULL REFERENCES eco_companies(id),role TEXT NOT NULL CHECK(role IN ('owner','manager','driver')),joined_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_company_invites(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES eco_companies(id),user TEXT NOT NULL REFERENCES accounts(user),invited_by TEXT NOT NULL,status TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS eco_support(id TEXT PRIMARY KEY,user TEXT NOT NULL REFERENCES accounts(user),order_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
